def init_agent():
    return {'known': jnp.full((9,), -1, jnp.int32),
            'positions': jnp.zeros((9, 2), jnp.int32),
            'evidence': jnp.zeros((1680,), jnp.float32)}


def beliefs(obs, known, evidence):
    assignments = jnp.asarray(ASSIGNMENTS, jnp.int32)
    feasible = jnp.all((known[None, :] < 0) | (assignments == known[None, :]), axis=1)
    hints = obs.node_features[9:, 3:6].astype(jnp.float32)
    attached = obs.adjacency_matrix[9:, :9].astype(jnp.float32)
    allowed = jnp.matmul(attached.T, hints)
    has_hint = jnp.sum(allowed, axis=1) > 0
    matches = jnp.take_along_axis(allowed[None, :, :], assignments[:, :, None], axis=2)[:, :, 0]
    logw = jnp.sum(jnp.where(has_hint[None, :] & (matches == 0), -4.0, 0.0), axis=1)
    behavior_logw = jnp.logaddexp(jnp.log(0.9) + evidence, jnp.log(0.1))
    weights = jax.nn.softmax(jnp.where(feasible, logw + behavior_logw, -1e8))
    onehot = jax.nn.one_hot(assignments, 3)
    marginals = jnp.einsum('n,nic->ic', weights, onehot)
    same = assignments[:, :, None] == assignments[:, None, :]
    pair = jnp.einsum('n,nij->ij', weights, same.astype(jnp.float32))
    return assignments, weights, marginals, pair


def move_values(positions, pair):
    ids = jnp.arange(729) // 81
    cells = jnp.arange(729) % 81
    destinations = jnp.stack((cells // 9, cells % 9), axis=-1)
    distance = jnp.abs(positions[:, None] - positions[None, :]).sum(-1)
    adjacency = (distance == 1).astype(jnp.float32)
    newdistance = jnp.abs(destinations[:, None, :] - positions[None, :, :]).sum(-1)
    others = ids[:, None] != jnp.arange(9)[None, :]
    newedges = (newdistance == 1) & others
    oldedges = adjacency[ids, :]
    delta = jnp.sum((newedges - oldedges) * pair[ids, :], axis=-1)
    # Nearby disconnected partners are easier to join on a later turn.
    proximity = jnp.sum(pair[ids, :] * others * (jnp.minimum(distance[ids], 6) - jnp.minimum(newdistance, 6)), axis=-1)
    compact = jnp.sum(newedges, axis=-1) - jnp.sum(oldedges, axis=-1)
    value = delta + 0.025 * proximity + 0.004 * compact
    return value, adjacency


def hypothetical_move_legality(positions, locked):
    ids = jnp.arange(729) // 81
    cells = jnp.arange(729) % 81
    destinations = jnp.stack((cells // 9, cells % 9), axis=-1)
    distance = jnp.abs(positions[:, None] - positions[None, :]).sum(-1)
    remaining = jnp.arange(9)[None, :] != jnp.arange(9)[:, None]
    reach = (distance[None] <= 1) & remaining[:, :, None] & remaining[:, None, :]
    def close(k, matrix):
        return matrix | (matrix[:, :, k, None] & matrix[:, None, k, :])
    reach = jax.lax.fori_loop(0, 9, close, reach)
    components = jnp.sum(reach.astype(jnp.int32) * (1 << jnp.arange(9))[None, None, :], axis=-1)
    newdistance = jnp.abs(destinations[:, None, :] - positions[None, :, :]).sum(-1)
    neighbors = (newdistance == 1) & (ids[:, None] != jnp.arange(9)[None, :])
    covered = jnp.bitwise_or.reduce(jnp.where(neighbors, components[ids], 0), axis=-1)
    return (~locked[ids]) & jnp.all(newdistance != 0, axis=-1) & (covered == (511 ^ (1 << ids)))


def observation_values(positions, locked, assignments, weights, marginals, pair):
    onehot = jax.nn.one_hot(assignments, 3).reshape((1680, 27))
    same = (assignments[:, :, None] == assignments[:, None, :]).reshape((1680, 81)).astype(jnp.float32)
    joint = jnp.matmul((weights[:, None] * onehot).T, same, precision=jax.lax.Precision.HIGHEST)
    conditional_pair = (joint / jnp.maximum(marginals.reshape((27, 1)), 1e-8)).reshape((27, 9, 9))
    values, _ = jax.vmap(move_values, in_axes=(None, 0))(positions, conditional_pair)
    legal = hypothetical_move_legality(positions, locked)
    best_value = jnp.max(jnp.where(legal[None], values, -1e6), axis=-1).reshape((9, 3))
    return jnp.sum(marginals * best_value, axis=-1)


def completion_probabilities(positions, adjacency, weights):
    triples = jnp.asarray(TRIPLES, jnp.int32)
    groups = jnp.asarray(ASSIGNMENT_GROUPS, jnp.int32)
    membership = jnp.sum(jax.nn.one_hot(triples, 9), axis=1)
    counts = adjacency[triples[:, 0], triples[:, 1]] + adjacency[triples[:, 0], triples[:, 2]] + adjacency[triples[:, 1], triples[:, 2]]
    connected = counts >= 2
    group_connected = connected[groups]
    others_connected = jnp.roll(group_connected, 1, axis=1) & jnp.roll(group_connected, 2, axis=1)
    finishing_weights = jnp.zeros((84,), jnp.float32).at[groups.reshape(-1)].add((weights[:, None] * others_connected).reshape(-1))
    ids = jnp.arange(729) // 81
    cells = jnp.arange(729) % 81
    destination = jnp.stack((cells // 9, cells % 9), axis=-1)
    newadj = (jnp.abs(destination[:, None] - positions[None]).sum(-1) == 1) & (ids[:, None] != jnp.arange(9)[None, :])
    delta = newadj.astype(jnp.float32) - adjacency[ids]
    newcounts = counts[None] + jnp.matmul(delta, membership.T)
    involved = membership[:, ids].T > 0
    return jnp.sum((newcounts >= 2) * involved * finishing_weights[None], axis=-1)


def partner_destination_evidence(old_positions, positions, locked, seen, moved, assignments):
    onehot = jax.nn.one_hot(assignments, 3)
    remaining = 3.0 - jnp.sum(onehot * seen[None, :, None], axis=1)
    unknown_count = jnp.sum(~seen).astype(jnp.float32)
    remaining_for_card = jnp.take_along_axis(remaining, assignments, axis=1)
    same = (assignments == assignments[:, moved, None]).astype(jnp.float32)
    both_unknown = jnp.sum(remaining * (remaining - 1.0), axis=-1) / jnp.maximum(unknown_count * (unknown_count - 1.0), 1.0)
    pair_row = jnp.where(seen[moved],
        jnp.where(seen[None], same, remaining_for_card[:, moved, None] / jnp.maximum(unknown_count, 1.0)),
        jnp.where(seen[None], remaining_for_card / jnp.maximum(unknown_count, 1.0), both_unknown[:, None]))
    pair_row = pair_row * (jnp.arange(9) != moved)[None]
    cells = jnp.arange(81)
    destinations = jnp.stack((cells // 9, cells % 9), axis=-1)
    newdist = jnp.abs(destinations[:, None] - old_positions[None]).sum(-1)
    newadj = ((newdist == 1) & (jnp.arange(9)[None] != moved)).astype(jnp.float32)
    utilities = jnp.matmul(pair_row, (newadj - 0.025 * jnp.minimum(newdist, 6)).T)
    legal = hypothetical_move_legality(old_positions, locked).reshape((9, 81))[moved]
    likelihood = 0.85 * jax.nn.softmax(jnp.where(legal[None], 5.0 * utilities, -1e8), axis=1) + 0.15 / jnp.maximum(jnp.sum(legal), 1)
    chosen_cell = positions[moved, 0] * 9 + positions[moved, 1]
    return jnp.log(jnp.maximum(likelihood[:, chosen_cell], 1e-8)) + jnp.log(jnp.maximum(jnp.sum(legal), 1))


def agent_act(obs, reset, memory, rng):
    memory = jax.tree.map(lambda initial, old: jnp.where(reset, initial, old), init_agent(), memory)
    features = obs.node_features
    visible = jnp.sum(features[:9, :3], axis=-1) > 0
    known = jnp.where(visible, jnp.argmax(features[:9, :3], axis=-1), memory['known'])
    assignments = jnp.asarray(ASSIGNMENTS, jnp.int32)
    changed = jnp.any(obs.positions != memory['positions'], axis=-1)
    moved = jnp.argmax(changed)
    partner_move = (features[0, 10] == 0) & (features[0, 11] == 3) & jnp.any(changed) & (~reset)
    seen = features[:9, 9] > 0
    update = partner_destination_evidence(memory['positions'], obs.positions, features[:9, 8] > 0, seen, moved, assignments)
    evidence = memory['evidence'] + jnp.where(partner_move, update, 0.0)
    evidence = jnp.clip(evidence, -20.0, 20.0)
    assignments, weights, marginals, pair = beliefs(obs, known, evidence)
    move_score, adjacency = move_values(obs.positions, pair)
    finish_probability = completion_probabilities(obs.positions, adjacency, weights)
    last_turn = jnp.all(jnp.sum(features[9:, 3:6], axis=-1) > 0) & (jnp.sum(features[9:, 8]) == 3)
    move_score = jnp.where(last_turn, 100.0 * finish_probability + 0.01 * move_score, move_score + 2.0 * finish_probability)
    move_legal = obs.legal_actions[10:739]
    best_move = jnp.argmax(jnp.where(move_legal, move_score, -1e9)) + 10
    top_values, top_indices = jax.lax.top_k(jnp.where(move_legal, move_score, -1e9), 12)
    def after_move(index):
        card = index // 81
        cell = index % 81
        return obs.positions.at[card].set(jnp.stack((cell // 9, cell % 9)))
    future_positions = jax.vmap(after_move)(top_indices)
    future_values, _ = jax.vmap(move_values, in_axes=(0, None))(future_positions, pair)
    future_legal = jax.vmap(hypothetical_move_legality, in_axes=(0, None))(future_positions, features[:9, 8] > 0)
    continuation = jnp.max(jnp.where(future_legal, future_values, -1e6), axis=-1)
    search_values = top_values + 0.35 * continuation * (1.0 - finish_probability[top_indices])
    planned_move = 10 + top_indices[jnp.argmax(search_values)]
    best_move = jnp.where(last_turn, best_move, planned_move)
    same = assignments[:, :, None] == assignments[:, None, :]
    edge_count = jnp.sum(same * adjacency[None], axis=(1, 2)) * 0.5
    solved_prob = jnp.sum(weights * (edge_count >= 5.99))

    entropy = -jnp.sum(marginals * jnp.log(jnp.maximum(marginals, 1e-8)), axis=-1)
    degree = jnp.sum(adjacency, axis=-1)
    other_seen = features[:9, 9].astype(jnp.float32)
    information_value = observation_values(obs.positions, features[:9, 8] > 0, assignments, weights, marginals, pair)
    observation_score = information_value + 0.10 * entropy + 0.002 * entropy * (4 - degree) + 0.10 * entropy * (1.0 - other_seen)
    observe = jnp.argmax(jnp.where(obs.legal_actions[1:10], observation_score, -1e9)) + 1
    revealed = jnp.sum(features[9:, 3:6], axis=-1) > 0
    placed = features[9:, 8] > 0
    current_value = jnp.sum(jnp.where(~revealed, 5.0, jnp.where(placed, 1.0, 2.0)))
    stop_threshold = jnp.maximum(0.80, (current_value - 1.0) / jnp.maximum(current_value, 1.0))
    observe = jnp.where((features[0, 11] == 0) & (solved_prob > stop_threshold), 1067, observe)

    hint_colors = features[9:, 3:6].astype(jnp.float32)
    correctness = jnp.matmul(hint_colors, marginals.T)
    same_degree = jnp.sum(pair * adjacency, axis=-1)
    stable = same_degree + 0.20 * degree
    hint_card_score = 8.0 * correctness + stable[None, :] + 0.10 * (1.0 - other_seen)[None, :]
    cells = obs.positions[:, 0] * 9 + obs.positions[:, 1]
    hint_actions = 743 + jnp.arange(4)[:, None] * 81 + cells[None, :]
    placement_score = jnp.where(obs.legal_actions[hint_actions], hint_card_score, -1e9)
    place_index = jnp.argmax(placement_score)
    placement = hint_actions.reshape(-1)[place_index]
    reveal = 739 + jnp.argmax(obs.legal_actions[739:743])
    singleton = jnp.sum(hint_colors, axis=-1) == 1
    informative_early = (correctness > 0.995) & (same_degree[None, :] > jnp.where(singleton[:, None], 0.9, 0.95)) & (other_seen[None, :] == 0)
    informative_early = informative_early & obs.legal_actions[hint_actions]
    early_index = jnp.argmax(jnp.where(informative_early, hint_card_score, -1e9))
    early_placement = hint_actions.reshape(-1)[early_index]
    hint_action = jnp.where(jnp.any(obs.legal_actions[739:743]), reveal, placement)
    hint_action = jnp.where(jnp.any(informative_early), early_placement, hint_action)
    substep = features[0, 11]
    action = jnp.where(substep < 2, observe, jnp.where(substep == 2, best_move, hint_action))
    action = jnp.where(features[0, 10], action, 0).astype(jnp.int32)
    action = jnp.where(obs.legal_actions[action], action, jnp.argmax(obs.legal_actions)).astype(jnp.int32)
    next_memory = {'known': known, 'positions': obs.positions, 'evidence': evidence}
    return action, next_memory, {'solved_probability': solved_prob, 'known': known, 'expected_edges': jnp.sum(pair * adjacency) * 0.5, 'max_belief': jnp.max(weights)}
